137	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
138	        }
139	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
140	    }
141	
142	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
143	    @Override
144	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
145	        HttpHeaders headers = new HttpHeaders();
146	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
147	        if (owner.getRegistrationDate() == null) {
148	            owner.setRegistrationDate(LocalDate.now());
149	        }
150	        // A supplied registration date may not be later than the server's current date.
151	        if (owner.getRegistrationDate().isAfter(LocalDate.now())) {
152	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
153	        }
154	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
155	        LocalDate registrationDate = owner.getRegistrationDate();
156	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
157	            .map(Owner::getRegistrationDate)
158	            .filter(registrationDate::equals)
159	            .count();
160	        if (ownersCreatedThatDay >= 100) {
161	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
162	        }
163	        String address = normalizedAddress(owner);
164	        if (address == null) {
165	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
166	        }
167	        owner.setAddress(address);
168	        String telephone = telephoneNormalizer.normalize(owner.getTelephone());
169	        if (telephone == null) {
170	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
171	        }
172	        if (!telephoneNormalizer.hasValidNationalNumberLength(telephone)) {
173	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
174	        }
175	        owner.setTelephone(telephone);
176	        String email = owner.getEmail();
177	        if (email != null) {
178	            email = email.trim();
179	            if (!EMAIL_PATTERN.matcher(email).matches()) {
180	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
181	            }
182	            String domain = email.substring(email.indexOf('@') + 1).toLowerCase(Locale.ROOT);
183	            if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
184	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
185	            }
186	            owner.setEmail(email.toLowerCase(Locale.ROOT));
187	        }
188	        // A postcode is optional, but when supplied it must be four digits and valid for the
189	        // owner's city per the fixed region table; a city with no known region accepts any
190	        // 4-digit postcode. Reject an out-of-range or malformed postcode with 400.
191	        String postcode = owner.getPostcode();
192	        if (postcode != null) {
193	            if (!POSTCODE_PATTERN.matcher(postcode).matches()
194	                    || !cityRegionResolver.isPostcodeValidForCity(owner.getCity(), postcode)) {
195	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
196	            }
197	        }
198	        // The owner's telephone and email are now in their canonical, stored form.
199	        // The household id is deterministic: owners with the same normalized last name and
200	        // postcode share it automatically. Assign it unconditionally before the duplicate
201	        // checks so both the household-duplicate rule and the identity-key rule key off the
202	        // same computed id.
203	        owner.setHouseholdId(householdResolver.householdId(owner));
204	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
205	        boolean householdMember = householdResolver.householdExists(owner);
206	        // Because the household is keyed on (lastName, postcode), a second owner sharing an
207	        // existing owner's household is a household duplicate and is rejected with 409. The
208	        // 'sharesHousehold' flag only bypasses this block, declaring a deliberate member; it
209	        // no longer creates the link, which the deterministic id now does on its own.
210	        if (householdMember && !sharesHousehold) {
211	            return new ResponseEntity<>(HttpStatus.CONFLICT);
212	        }
213	        if (isDuplicateOwner(owner)) {
214	            return new ResponseEntity<>(HttpStatus.CONFLICT);
215	        }
216	        String cityKey = IdentityUtils.normalizeIdentity(owner.getCity());
217	        long ownersInCity = this.clinicService.findAllOwners().stream()
218	            .filter(existing -> IdentityUtils.normalizeIdentity(existing.getCity()).equals(cityKey))
219	            .count();
220	        if (ownersInCity >= 50) {
221	            return new ResponseEntity<>(HttpStatus.CONFLICT);
222	        }
223	        owner.setCustomerCode(customerCode(owner));
224	        owner.setNamesakeCount(namesakeCount(owner));
225	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
226	        owner.setBulkSignupWarning(ownersCreatedThatDay > 80);
227	        // Soft-match: the candidate has already cleared the hard-duplicate check, but it may
228	        // still share an existing owner's last name and postcode while carrying a different
229	        // telephone. When it does, it is created but flagged as a possible duplicate of that
230	        // existing owner; otherwise the flag is false and no reference is recorded. A declared
231	        // household member (created via 'sharesHousehold') is not a suspected duplicate, so it
232	        // is never flagged.
233	        Integer possibleDuplicateOf = (sharesHousehold && householdMember) ? null : possibleDuplicateOf(owner);
234	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
235	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
236	        this.clinicService.saveOwner(owner);
237	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
238	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
239	            ownerMapper.membershipLevel(owner), owner.getMembershipNumber());
240	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
241	        headers.setLocation(UriComponentsBuilder.newInstance()
242	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
243	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
244	    }
245	
246	    /**
247	     * The owner's postal address in the single canonical form under which it is stored, or
248	     * {@code null} when the owner supplies no usable address. An owner may supply its address
249	     * in EITHER form: the structured {@code addressLine1} (with an optional {@code addressLine2})
250	     * is preferred, and the flat {@code address} remains accepted for backward compatibility.
251	     *
252	     * <p>Normalization by {@link AddressNormalizer} is applied to whichever fields are supplied.
253	     * When a non-blank {@code addressLine1} is present the owner's structured fields are replaced
254	     * with their normalized values (a blank or absent {@code addressLine2} is cleared to
255	     * {@code null}) and the returned address is composed as the normalized {@code addressLine1},
256	     * with a single space and the normalized {@code addressLine2} appended when present. Otherwise
257	     * the flat {@code address} is normalized and the structured fields are cleared. A blank result
258	     * (no usable address in either form) has no canonical form and is reported as {@code null} so
259	     * the caller can reject the request with 400.
260	     *
261	     * <p>This is the single point at which an owner's address is resolved and normalized on
262	     * create, so every rule keyed on the stored address reads the one value produced here.
263	     *
264	     * @param owner the owner about to be created
265	     * @return the canonical stored address, or {@code null} when the owner supplies none
266	     */
267	    private String normalizedAddress(Owner owner) {
268	        String rawLine1 = owner.getAddressLine1();
269	        if (rawLine1 != null && !rawLine1.isBlank()) {
270	            String line1 = addressNormalizer.normalize(rawLine1);
271	            String line2 = addressNormalizer.normalize(owner.getAddressLine2());
272	            owner.setAddressLine1(line1);
273	            owner.setAddressLine2(line2.isBlank() ? null : line2);
274	            return line2.isBlank() ? line1 : line1 + " " + line2;
275	        }
276	        owner.setAddressLine1(null);
277	        owner.setAddressLine2(null);
278	        String address = addressNormalizer.normalize(owner.getAddress());
279	        return address.isBlank() ? null : address;
280	    }
281	
282	    /**
283	     * Whether {@code candidate} collides with an already-registered owner under the single
284	     * identity rule enforced on create. This is the one point at which a new owner is
285	     * rejected as a duplicate (HTTP 409): all duplicate detection is consolidated into the
286	     * derived {@link OwnerMapper#identityKey identityKey} — the normalized telephone, the
287	     * email (or an empty string when absent) and the householdId joined by '|'. The
288	     * candidate clashes only when its WHOLE identityKey equals an existing owner's; because
289	     * the telephone is part of the key, two members of the same household (same householdId)
290	     * with different telephones have different identityKeys and are both allowed.
291	     *
292	     * <p>The candidate arrives with its telephone and email already normalized and its
293	     * household id already derived, and each existing owner is stored in the same canonical
294	     * form, so an identityKey match means the two owners are genuinely the same identity.
295	     *
296	     * @param candidate the fully-normalized owner about to be created
297	     * @return {@code true} if an existing owner already occupies the candidate's identityKey
298	     */
299	    private boolean isDuplicateOwner(Owner candidate) {
300	        String identityKey = OwnerMapper.identityKey(candidate);
301	        return this.clinicService.findAllOwners().stream()
302	            .map(OwnerMapper::identityKey)
303	            .anyMatch(identityKey::equals);
304	    }
305	
306	    /**
307	     * The id of the existing owner the fully-normalized {@code candidate} soft-matches, or
308	     * {@code null} when there is none. A soft match is an owner that is not a hard duplicate
309	     * (its whole identityKey differs) yet shares the candidate's normalized last name and its
310	     * postcode while carrying a different telephone — a likely re-registration of the same
311	     * person under a new number. Both must supply a postcode for a match to be possible; when
312	     * several existing owners qualify the lowest id is returned so the result is deterministic.
313	     *
314	     * @param candidate the fully-normalized owner about to be created
315	     * @return the matching existing owner's id, or {@code null} if the candidate is no soft match
316	     */
317	    private Integer possibleDuplicateOf(Owner candidate) {
318	        String postcode = candidate.getPostcode();
319	        if (postcode == null) {
320	            return null;
321	        }
322	        String lastNameKey = IdentityUtils.normalizeIdentity(candidate.getLastName());
323	        return this.clinicService.findAllOwners().stream()
324	            .filter(existing -> IdentityUtils.normalizeIdentity(existing.getLastName()).equals(lastNameKey)
325	                && postcode.equals(existing.getPostcode())
326	                && !postcode.isBlank()
327	                && !java.util.Objects.equals(candidate.getTelephone(), existing.getTelephone()))
328	            .map(Owner::getId)
329	            .filter(java.util.Objects::nonNull)
330	            .min(Integer::compareTo)
331	            .orElse(null);
332	    }
333	
334	    /**
335	     * Build the customer code assigned to {@code owner} on create, formatted
336	     * {@code '<REGION>-<HASH8>'}: REGION is the region code derived from the owner's postcode
337	     * (falling back to the city) via {@link CityRegionResolver}, and HASH8 is the first eight
338	     * upper-case hex characters of the SHA-256 digest of the normalized telephone concatenated
339	     * with the last name (e.g. 'NSW-1A2B3C4D'). There is no per-city sequence.
340	     *
341	     * <p>When the computed code collides with an already-registered owner's customerCode it is
342	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that
343	     * makes it unique (e.g. 'NSW-1A2B3C4D-2'), and the unique code is returned.
344	     */
345	    private String customerCode(Owner owner) {
346	        String region = cityRegionResolver.regionFor(owner.getCity(), owner.getPostcode());
347	        String hash8 = HashUtils.sha256HexPrefix(owner.getTelephone() + owner.getLastName(), 8);
348	        String base = region + "-" + hash8;
349	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
350	            .map(Owner::getCustomerCode)
351	            .filter(java.util.Objects::nonNull)
352	            .collect(java.util.stream.Collectors.toSet());
353	        if (!existing.contains(base)) {
354	            return base;
355	        }
356	        int n = 2;
357	        while (existing.contains(base + "-" + n)) {
358	            n++;
359	        }
360	        return base + "-" + n;
361	    }
362	
363	    /**
364	     * The number of existing owners that share {@code owner}'s firstName and lastName,
365	     * compared case-insensitively. The candidate is not yet stored at the point this is
366	     * assigned, so it does not count itself. This is the value stored as the owner's
367	     * namesakeCount on create.
368	     */
369	    private int namesakeCount(Owner owner) {
370	        return (int) this.clinicService.findAllOwners().stream()
371	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName())
372	                && owner.getLastName().equalsIgnoreCase(existing.getLastName()))
373	            .count();
374	    }
375	
376	    /**
377	     * Roll a registration date forward to the next business day: a Saturday or Sunday
378	     * advances to the following Monday, and a weekday is returned unchanged.
379	     */
380	    private static LocalDate toBusinessDay(LocalDate date) {
381	        return switch (date.getDayOfWeek()) {
382	            case SATURDAY -> date.plusDays(2);
383	            case SUNDAY -> date.plusDays(1);
384	            default -> date;
385	        };
386	    }
387	
388	    /**
389	     * Build the membership number assigned on create, formatted
390	     * {@code '<customerCode>-M<YY>'} where YY is the last two digits of the
391	     * {@code registrationDate} year (e.g. 'NSW-1A2B3C4D-M26').
392	     */
393	    private static String membershipNumber(String customerCode, LocalDate registrationDate) {
394	        String yy = String.format("%02d", registrationDate.getYear() % 100);
395	        return customerCode + "-M" + yy;
396	    }
397	
398	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
399	    @Override
400	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
401	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
402	        if (currentOwner == null) {
403	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
404	        }
405	        currentOwner.setAddress(ownerFieldsDto.getAddress());
406	        currentOwner.setCity(ownerFieldsDto.getCity());
407	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
408	        currentOwner.setLastName(ownerFieldsDto.getLastName());
409	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
410	        this.clinicService.saveOwner(currentOwner);
411	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
412	    }
413	
414	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
415	    @Transactional
416	    @Override
417	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
418	        Owner owner = this.clinicService.findOwnerById(ownerId);
419	        if (owner == null) {
420	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
421	        }
422	        this.clinicService.deleteOwner(owner);
423	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
424	    }
425	
426	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
427	    @Override
428	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
429	        Owner owner = this.clinicService.findOwnerById(ownerId);
430	        if (owner == null) {
431	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
432	        }
433	        HttpHeaders headers = new HttpHeaders();
434	        Pet pet = petMapper.toPet(petFieldsDto);
435	        owner.setId(ownerId);
436	        pet.setOwner(owner);
437	        pet.getType().setName(null);
438	        this.clinicService.savePet(pet);
439	        PetDto petDto = petMapper.toPetDto(pet);
440	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
441	            .buildAndExpand(pet.getId()).toUri());
442	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
443	    }
444	
445	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
446	    @Override
447	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
448	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
449	        if (currentOwner != null) {
450	            Pet currentPet = this.clinicService.findPetById(petId);
451	            if (currentPet != null) {
452	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
453	                currentPet.setName(petFieldsDto.getName());
454	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
455	                this.clinicService.savePet(currentPet);
456	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
457	            }
458	        }
459	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
460	    }
461	
462	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
463	    @Override
464	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
465	        HttpHeaders headers = new HttpHeaders();
466	        Visit visit = visitMapper.toVisit(visitFieldsDto);
467	        Pet pet = new Pet();
468	        pet.setId(petId);
469	        visit.setPet(pet);
470	        this.clinicService.saveVisit(visit);
471	        VisitDto visitDto = visitMapper.toVisitDto(visit);
472	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
473	            .buildAndExpand(visit.getId()).toUri());
474	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
475	    }
476	
477	
478	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
479	    @Override
480	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
481	        Owner owner = this.clinicService.findOwnerById(ownerId);
482	        if (owner != null) {
483	            Pet pet = owner.getPet(petId);
484	            if (pet != null) {
485	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
486	            }
487	        }
488	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
489	    }
490	}
